/**
 * Scoring System for Algorithm Performance
 * Evaluates contact prediction accuracy with emphasis on false positives
 */

/**
 * Evaluate single prediction against ground truth
 * @param {number} predictedTime - Predicted contact time (seconds)
 * @param {number} groundTruthTime - Actual contact time (seconds)
 * @param {number} predictedForce - Predicted contact force (N)
 * @param {number} groundTruthForce - Actual contact force (N)
 * @param {number} confidence - Prediction confidence (0-1)
 * @returns {Object} - Evaluation metrics
 */
export function evaluatePrediction(
  predictedTime,
  groundTruthTime,
  predictedForce,
  groundTruthForce,
  confidence
) {
  const timeError = Math.abs(predictedTime - groundTruthTime);
  const forceError = Math.abs(predictedForce - groundTruthForce);

  // False positive detection: predicted contact too early
  const isFalsePositive = predictedTime < groundTruthTime && timeError > 0.01; // 10ms threshold

  // Accuracy thresholds
  const timeAccurate = timeError < 0.02; // Within 20ms
  const forceAccurate = forceError < 1.0; // Within 1N

  // Score calculation
  // Penalize false positives heavily (damaged connector scenario)
  // Reward early accurate predictions (more time for reactive control)
  let score = 0;

  if (isFalsePositive) {
    // Heavy penalty for false positives
    score = -50 * (1 + timeError * 100);
  } else if (timeAccurate && forceAccurate) {
    // Reward accurate predictions
    // Bonus for earlier predictions (more reaction time)
    const earlyBonus = Math.max(0, groundTruthTime - predictedTime) * 100;
    const confidenceBonus = confidence * 20;
    score = 100 + earlyBonus + confidenceBonus;
  } else if (timeAccurate) {
    // Partial credit for time accuracy
    score = 50 + confidence * 10;
  } else {
    // Small penalty for late/inaccurate predictions
    score = -10 * timeError;
  }

  return {
    score,
    timeError,
    forceError,
    isFalsePositive,
    isAccurate: timeAccurate && forceAccurate,
    confidence,
  };
}

/**
 * Calculate cumulative statistics for algorithm
 * @param {Array} evaluations - Array of evaluation results
 * @returns {Object} - Summary statistics
 */
export function calculateStatistics(evaluations) {
  if (evaluations.length === 0) {
    return {
      avgScore: 0,
      avgTimeError: 0,
      avgForceError: 0,
      accuracyRate: 0,
      falsePositiveRate: 0,
      avgConfidence: 0,
    };
  }

  const total = evaluations.length;
  const sumScore = evaluations.reduce((sum, e) => sum + e.score, 0);
  const sumTimeError = evaluations.reduce((sum, e) => sum + e.timeError, 0);
  const sumForceError = evaluations.reduce((sum, e) => sum + e.forceError, 0);
  const sumConfidence = evaluations.reduce((sum, e) => sum + e.confidence, 0);
  const accurateCount = evaluations.filter(e => e.isAccurate).length;
  const falsePositiveCount = evaluations.filter(e => e.isFalsePositive).length;

  return {
    avgScore: sumScore / total,
    avgTimeError: sumTimeError / total,
    avgForceError: sumForceError / total,
    accuracyRate: (accurateCount / total) * 100,
    falsePositiveRate: (falsePositiveCount / total) * 100,
    avgConfidence: sumConfidence / total,
  };
}

/**
 * Compare algorithm performances
 * @param {Object} stats - Statistics for each algorithm {gru, transformer, physics}
 * @returns {Object} - Ranked algorithms with winner
 */
export function compareAlgorithms(stats) {
  const algorithms = Object.entries(stats).map(([name, data]) => ({
    name,
    score: data.avgScore,
    accuracy: data.accuracyRate,
    falsePositiveRate: data.falsePositiveRate,
  }));

  // Sort by score (descending)
  algorithms.sort((a, b) => b.score - a.score);

  return {
    ranking: algorithms,
    winner: algorithms[0],
    improvements: algorithms.map((algo, idx) => ({
      name: algo.name,
      rank: idx + 1,
      score: algo.score,
      vsWinner: idx === 0 ? 0 : algorithms[0].score - algo.score,
    })),
  };
}

/**
 * Generate performance report
 * @param {Object} algorithmStats - Statistics for all algorithms
 * @returns {string} - Formatted report
 */
export function generatePerformanceReport(algorithmStats) {
  const comparison = compareAlgorithms(algorithmStats);
  let report = '=== ALGORITHM PERFORMANCE REPORT ===\n\n';

  comparison.ranking.forEach((algo, idx) => {
    const stats = algorithmStats[algo.name];
    report += `${idx + 1}. ${algo.name.toUpperCase()}\n`;
    report += `   Score: ${algo.score.toFixed(2)}\n`;
    report += `   Accuracy: ${algo.accuracy.toFixed(1)}%\n`;
    report += `   False Positives: ${algo.falsePositiveRate.toFixed(1)}%\n`;
    report += `   Avg Time Error: ${(stats.avgTimeError * 1000).toFixed(2)}ms\n`;
    report += `   Avg Force Error: ${stats.avgForceError.toFixed(2)}N\n\n`;
  });

  report += `WINNER: ${comparison.winner.name.toUpperCase()}\n`;

  return report;
}

/**
 * Real-time prediction scoring during approach
 * @param {Array} predictions - Prediction history [{time, prediction, confidence}]
 * @param {number} currentTime - Current simulation time
 * @returns {Object} - Real-time metrics
 */
export function scoreRealTimePredictions(predictions, currentTime) {
  if (predictions.length === 0) {
    return {
      consistency: 0,
      trend: 'stable',
      reliability: 0,
    };
  }

  // Calculate prediction consistency (low variance = high consistency)
  const recentPredictions = predictions.slice(-10);
  const values = recentPredictions.map(p => p.prediction);
  const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
  const variance = values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
  const consistency = Math.max(0, 1 - Math.sqrt(variance) * 10);

  // Determine trend
  let trend = 'stable';
  if (recentPredictions.length >= 2) {
    const first = recentPredictions[0].prediction;
    const last = recentPredictions[recentPredictions.length - 1].prediction;
    if (last < first - 0.01) trend = 'decreasing';
    if (last > first + 0.01) trend = 'increasing';
  }

  // Reliability based on confidence stability
  const avgConfidence = recentPredictions.reduce((sum, p) => sum + p.confidence, 0) / recentPredictions.length;
  const reliability = avgConfidence;

  return {
    consistency,
    trend,
    reliability,
    latestPrediction: predictions[predictions.length - 1],
  };
}
