import { useRef, useState, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Text } from '@react-three/drei';
import * as THREE from 'three';
import useStore from '../store';
import { calculateProximityField } from '../utils/sensorModels';
import './GripperEditor.css';

function Gripper({ onFingerClick }) {
  return (
    <group>
      {/* Base */}
      <mesh position={[0, -0.04, 0]}>
        <boxGeometry args={[0.06, 0.02, 0.04]} />
        <meshStandardMaterial color="#2a4a7a" metalness={0.8} roughness={0.2} />
      </mesh>

      {/* Left Finger */}
      <mesh position={[-0.02, 0, 0]} onClick={() => onFingerClick({ x: -0.02, y: 0, z: 0 })}>
        <boxGeometry args={[0.015, 0.08, 0.02]} />
        <meshStandardMaterial color="#3a5a8a" metalness={0.7} roughness={0.3} />
      </mesh>

      {/* Right Finger */}
      <mesh position={[0.02, 0, 0]} onClick={() => onFingerClick({ x: 0.02, y: 0, z: 0 })}>
        <boxGeometry args={[0.015, 0.08, 0.02]} />
        <meshStandardMaterial color="#3a5a8a" metalness={0.7} roughness={0.3} />
      </mesh>

      {/* Finger tips */}
      <mesh position={[-0.02, 0.04, 0]}>
        <boxGeometry args={[0.015, 0.01, 0.02]} />
        <meshStandardMaterial color="#4a6a9a" metalness={0.6} roughness={0.4} />
      </mesh>
      <mesh position={[0.02, 0.04, 0]}>
        <boxGeometry args={[0.015, 0.01, 0.02]} />
        <meshStandardMaterial color="#4a6a9a" metalness={0.6} roughness={0.4} />
      </mesh>
    </group>
  );
}

function TargetObject() {
  return (
    <mesh position={[0, 0.15, 0]}>
      <cylinderGeometry args={[0.01, 0.01, 0.03, 16]} />
      <meshStandardMaterial color="#ff8800" emissive="#ff4400" emissiveIntensity={0.5} />
    </mesh>
  );
}

function SensorMarker({ position, type, id, isSelected, onClick }) {
  const meshRef = useRef();

  useFrame(({ clock }) => {
    if (meshRef.current && isSelected) {
      meshRef.current.scale.setScalar(1 + Math.sin(clock.elapsedTime * 3) * 0.1);
    }
  });

  const color = type === 'capacitive' ? '#00ff88' : '#ff0088';

  return (
    <group position={[position.x, position.y, position.z]}>
      <mesh ref={meshRef} onClick={onClick}>
        <sphereGeometry args={[0.003, 16, 16]} />
        <meshStandardMaterial
          color={color}
          emissive={color}
          emissiveIntensity={isSelected ? 1.5 : 0.8}
        />
      </mesh>
      <pointLight
        position={[0, 0, 0]}
        color={color}
        intensity={0.5}
        distance={0.03}
      />
    </group>
  );
}

function ProximityField({ sensors }) {
  const meshRef = useRef();
  const { showProximityField } = useStore();

  useEffect(() => {
    if (!meshRef.current || sensors.length === 0 || !showProximityField) return;

    const geometry = meshRef.current.geometry;
    const positions = geometry.attributes.position;
    const colors = new Float32Array(positions.count * 3);

    for (let i = 0; i < positions.count; i++) {
      const x = positions.getX(i);
      const y = positions.getY(i);
      const z = positions.getZ(i);

      const fieldValue = calculateProximityField(sensors, { x, y, z });

      // Color gradient based on field strength
      const r = fieldValue;
      const g = fieldValue * 0.8;
      const b = fieldValue * 0.3;

      colors[i * 3] = r;
      colors[i * 3 + 1] = g;
      colors[i * 3 + 2] = b;
    }

    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  }, [sensors, showProximityField]);

  if (sensors.length === 0 || !showProximityField) return null;

  return (
    <mesh ref={meshRef} position={[0, 0.075, 0]}>
      <boxGeometry args={[0.08, 0.15, 0.04, 20, 30, 10]} />
      <meshBasicMaterial
        vertexColors
        transparent
        opacity={0.3}
        side={THREE.DoubleSide}
      />
    </mesh>
  );
}

function Scene() {
  const { sensors, addSensor, sensorType, showProximityField } = useStore();
  const [selectedSensorId, setSelectedSensorId] = useState(null);

  const handleFingerClick = (event) => {
    event.stopPropagation();

    // Get click position in world space
    const point = event.point;

    // Snap to finger surface
    const x = point.x < 0 ? -0.02 : 0.02;
    const y = Math.max(-0.03, Math.min(0.03, point.y));
    const z = Math.max(-0.01, Math.min(0.01, point.z));

    addSensor({ x, y, z });
  };

  return (
    <>
      <color attach="background" args={['#0a0a0f']} />
      <ambientLight intensity={0.4} />
      <pointLight position={[0.1, 0.1, 0.1]} intensity={0.8} />
      <pointLight position={[-0.1, 0.1, 0.1]} intensity={0.8} color="#0088ff" />

      <Gripper onFingerClick={handleFingerClick} />
      <TargetObject />

      {sensors.map((sensor) => (
        <SensorMarker
          key={sensor.id}
          position={sensor.position}
          type={sensor.type}
          id={sensor.id}
          isSelected={sensor.id === selectedSensorId}
          onClick={(e) => {
            e.stopPropagation();
            setSelectedSensorId(sensor.id);
          }}
        />
      ))}

      <ProximityField sensors={sensors} />

      <Grid
        args={[0.2, 0.2]}
        cellSize={0.01}
        cellThickness={0.5}
        cellColor="#333"
        sectionSize={0.05}
        sectionThickness={1}
        sectionColor="#444"
        fadeDistance={0.3}
        fadeStrength={1}
        followCamera={false}
        position={[0, -0.05, 0]}
      />

      <Text
        position={[0, 0.18, 0]}
        fontSize={0.008}
        color="#ff8800"
        anchorX="center"
        anchorY="middle"
      >
        Target Connector
      </Text>

      <OrbitControls
        enablePan={true}
        enableZoom={true}
        enableRotate={true}
        minDistance={0.1}
        maxDistance={0.5}
        target={[0, 0.05, 0]}
      />
    </>
  );
}

function GripperEditor() {
  const { sensors, showProximityField, toggleProximityField } = useStore();

  return (
    <div className="gripper-editor">
      <div className="canvas-container">
        <Canvas camera={{ position: [0.15, 0.1, 0.15], fov: 50 }}>
          <Scene />
        </Canvas>
      </div>

      <div className="editor-controls">
        <button onClick={toggleProximityField} className={showProximityField ? 'active' : ''}>
          {showProximityField ? '👁️ Hide' : '👁️ Show'} Proximity Field
        </button>
        <div className="sensor-count">
          Sensors: {sensors.length}
        </div>
        <div className="help-text">
          💡 Click on gripper fingers to place sensors
        </div>
      </div>
    </div>
  );
}

export default GripperEditor;
