/**
 * Causal Transformer Model for Contact Prediction
 * Implements multi-head attention for sensor fusion
 */

/**
 * Positional Encoding
 * Adds temporal information to sensor embeddings
 */
class PositionalEncoding {
  constructor(dModel, maxLen = 100) {
    this.dModel = dModel;
    this.encodings = this.generateEncodings(maxLen, dModel);
  }

  generateEncodings(maxLen, dModel) {
    const encodings = [];
    for (let pos = 0; pos < maxLen; pos++) {
      const encoding = [];
      for (let i = 0; i < dModel; i++) {
        if (i % 2 === 0) {
          encoding.push(Math.sin(pos / Math.pow(10000, i / dModel)));
        } else {
          encoding.push(Math.cos(pos / Math.pow(10000, (i - 1) / dModel)));
        }
      }
      encodings.push(encoding);
    }
    return encodings;
  }

  encode(embeddings) {
    return embeddings.map((emb, pos) =>
      emb.map((val, i) => val + this.encodings[pos][i])
    );
  }
}

/**
 * Multi-Head Attention
 */
class MultiHeadAttention {
  constructor(dModel, numHeads) {
    this.dModel = dModel;
    this.numHeads = numHeads;
    this.dHead = Math.floor(dModel / numHeads);

    // Query, Key, Value projection matrices for each head
    this.Wq = this.initWeights(numHeads, dModel, this.dHead);
    this.Wk = this.initWeights(numHeads, dModel, this.dHead);
    this.Wv = this.initWeights(numHeads, dModel, this.dHead);
    this.Wo = this.initWeights(1, dModel, dModel)[0]; // Output projection
  }

  initWeights(numMatrices, rows, cols) {
    const matrices = [];
    for (let m = 0; m < numMatrices; m++) {
      const matrix = [];
      for (let i = 0; i < rows; i++) {
        matrix[i] = [];
        for (let j = 0; j < cols; j++) {
          matrix[i][j] = (Math.random() - 0.5) * Math.sqrt(2 / (rows + cols));
        }
      }
      matrices.push(matrix);
    }
    return matrices;
  }

  matmul(matrix, vector) {
    return matrix.map(row =>
      row.reduce((sum, weight, i) => sum + weight * (vector[i] || 0), 0)
    );
  }

  softmax(values) {
    const maxVal = Math.max(...values);
    const exps = values.map(v => Math.exp(v - maxVal));
    const sumExp = exps.reduce((sum, e) => sum + e, 0);
    return exps.map(e => e / sumExp);
  }

  /**
   * Scaled dot-product attention
   */
  attention(Q, K, V, mask = null) {
    const seqLen = Q.length;
    const dK = K[0].length;

    // Compute attention scores: Q * K^T / sqrt(d_k)
    const scores = [];
    for (let i = 0; i < seqLen; i++) {
      scores[i] = [];
      for (let j = 0; j < seqLen; j++) {
        let score = 0;
        for (let k = 0; k < dK; k++) {
          score += Q[i][k] * K[j][k];
        }
        score /= Math.sqrt(dK);

        // Apply causal mask (prevent attending to future)
        if (mask && j > i) {
          score = -Infinity;
        }

        scores[i][j] = score;
      }
    }

    // Apply softmax
    const attentionWeights = scores.map(row => this.softmax(row));

    // Weighted sum of values
    const output = [];
    for (let i = 0; i < seqLen; i++) {
      output[i] = new Array(V[0].length).fill(0);
      for (let j = 0; j < seqLen; j++) {
        for (let k = 0; k < V[0].length; k++) {
          output[i][k] += attentionWeights[i][j] * V[j][k];
        }
      }
    }

    return { output, attentionWeights };
  }

  forward(embeddings, causalMask = true) {
    const seqLen = embeddings.length;
    const headOutputs = [];

    // Process each attention head
    for (let h = 0; h < this.numHeads; h++) {
      // Project to Q, K, V
      const Q = embeddings.map(emb => this.matmul(this.Wq[h], emb));
      const K = embeddings.map(emb => this.matmul(this.Wk[h], emb));
      const V = embeddings.map(emb => this.matmul(this.Wv[h], emb));

      // Compute attention
      const { output } = this.attention(Q, K, V, causalMask);
      headOutputs.push(output);
    }

    // Concatenate heads and project
    const concatenated = [];
    for (let i = 0; i < seqLen; i++) {
      const concat = [];
      for (let h = 0; h < this.numHeads; h++) {
        concat.push(...headOutputs[h][i]);
      }
      // Pad to dModel if needed
      while (concat.length < this.dModel) concat.push(0);
      concatenated.push(this.matmul(this.Wo, concat.slice(0, this.dModel)));
    }

    return concatenated;
  }
}

/**
 * Transformer Encoder Layer
 */
class TransformerLayer {
  constructor(dModel, numHeads, dFF = null) {
    this.attention = new MultiHeadAttention(dModel, numHeads);
    this.dFF = dFF || dModel * 4;

    // Feed-forward network
    this.W1 = this.initWeights(this.dFF, dModel);
    this.b1 = new Array(this.dFF).fill(0);
    this.W2 = this.initWeights(dModel, this.dFF);
    this.b2 = new Array(dModel).fill(0);
  }

  initWeights(rows, cols) {
    const weights = [];
    for (let i = 0; i < rows; i++) {
      weights[i] = [];
      for (let j = 0; j < cols; j++) {
        weights[i][j] = (Math.random() - 0.5) * Math.sqrt(2 / (rows + cols));
      }
    }
    return weights;
  }

  relu(x) {
    return Math.max(0, x);
  }

  layerNorm(vector) {
    const mean = vector.reduce((sum, v) => sum + v, 0) / vector.length;
    const variance = vector.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / vector.length;
    const stdDev = Math.sqrt(variance + 1e-6);
    return vector.map(v => (v - mean) / stdDev);
  }

  feedForward(input) {
    // First layer with ReLU
    const hidden = this.W1.map((row, i) =>
      this.relu(row.reduce((sum, w, j) => sum + w * input[j], 0) + this.b1[i])
    );

    // Second layer
    const output = this.W2.map((row, i) =>
      row.reduce((sum, w, j) => sum + w * hidden[j], 0) + this.b2[i]
    );

    return output;
  }

  forward(embeddings) {
    // Multi-head attention with residual connection
    const attentionOut = this.attention.forward(embeddings, true);
    const afterAttention = embeddings.map((emb, i) =>
      this.layerNorm(emb.map((val, j) => val + attentionOut[i][j]))
    );

    // Feed-forward with residual connection
    const ffOut = afterAttention.map(emb => this.feedForward(emb));
    const output = afterAttention.map((emb, i) =>
      this.layerNorm(emb.map((val, j) => val + ffOut[i][j]))
    );

    return output;
  }
}

/**
 * Causal Transformer Model
 */
export class CausalTransformer {
  constructor(config = {}) {
    const {
      inputSize = 16,
      dModel = 64,
      numHeads = 4,
      numLayers = 2,
      sequenceLength = 20,
    } = config;

    this.inputSize = inputSize;
    this.dModel = dModel;
    this.sequenceLength = sequenceLength;

    // Input embedding
    this.embedding = this.initWeights(dModel, inputSize);

    // Positional encoding
    this.posEncoding = new PositionalEncoding(dModel, sequenceLength);

    // Transformer layers
    this.layers = [];
    for (let i = 0; i < numLayers; i++) {
      this.layers.push(new TransformerLayer(dModel, numHeads));
    }

    // Output projection
    this.outputLayer = this.initWeights(2, dModel); // [contact_time, contact_force]
    this.outputBias = [0, 0];

    // Learning history
    this.learningHistory = [];
  }

  initWeights(rows, cols) {
    const weights = [];
    for (let i = 0; i < rows; i++) {
      weights[i] = [];
      for (let j = 0; j < cols; j++) {
        weights[i][j] = (Math.random() - 0.5) * Math.sqrt(2 / (rows + cols));
      }
    }
    return weights;
  }

  /**
   * Embed input sequence
   */
  embed(sequence) {
    return sequence.map(input =>
      this.embedding.map(row =>
        row.reduce((sum, w, i) => sum + w * input[i], 0)
      )
    );
  }

  /**
   * Predict contact time and force
   */
  predict(sensorSequence) {
    // Normalize sequence length
    let sequence = [...sensorSequence];
    while (sequence.length < this.sequenceLength) {
      sequence.unshift(new Array(this.inputSize).fill(0));
    }
    sequence = sequence.slice(-this.sequenceLength);

    // Embed and add positional encoding
    let embeddings = this.embed(sequence);
    embeddings = this.posEncoding.encode(embeddings);

    // Pass through transformer layers
    for (const layer of this.layers) {
      embeddings = layer.forward(embeddings);
    }

    // Use final token for prediction
    const finalEmbedding = embeddings[embeddings.length - 1];

    // Output projection
    const output = this.outputLayer.map((row, i) =>
      row.reduce((sum, w, j) => sum + w * finalEmbedding[j], 0) + this.outputBias[i]
    );

    // Scale outputs
    const contactTime = Math.max(0, output[0] * 0.1);
    const contactForce = Math.max(0, output[1] * 10);

    // Calculate confidence from attention patterns
    const avgEmbedding = finalEmbedding.reduce((sum, v) => sum + Math.abs(v), 0) / finalEmbedding.length;
    const confidence = Math.min(1, avgEmbedding / 0.3);

    // Apply learned corrections
    const { adjustedTime, adjustedForce } = this.applyLearning(contactTime, contactForce);

    return {
      contactTime: adjustedTime,
      contactForce: adjustedForce,
      confidence,
      rawOutput: { contactTime, contactForce },
      embedding: finalEmbedding,
    };
  }

  applyLearning(contactTime, contactForce) {
    if (this.learningHistory.length < 3) {
      return { adjustedTime: contactTime, adjustedForce: contactForce };
    }

    const recent = this.learningHistory.slice(-8);
    const avgTimeError = recent.reduce((sum, h) => sum + h.timeError, 0) / recent.length;
    const avgForceError = recent.reduce((sum, h) => sum + h.forceError, 0) / recent.length;

    const learningRate = 0.25;
    return {
      adjustedTime: Math.max(0, contactTime - learningRate * avgTimeError),
      adjustedForce: Math.max(0, contactForce - learningRate * avgForceError),
    };
  }

  update(prediction, groundTruth) {
    this.learningHistory.push({
      timeError: prediction.contactTime - groundTruth.contactTime,
      forceError: prediction.contactForce - groundTruth.contactForce,
      timestamp: Date.now(),
    });

    if (this.learningHistory.length > 100) {
      this.learningHistory.shift();
    }
  }

  getStats() {
    if (this.learningHistory.length === 0) {
      return { avgTimeError: 0, avgForceError: 0, samples: 0 };
    }

    const recent = this.learningHistory.slice(-20);
    return {
      avgTimeError: recent.reduce((sum, h) => sum + Math.abs(h.timeError), 0) / recent.length,
      avgForceError: recent.reduce((sum, h) => sum + Math.abs(h.forceError), 0) / recent.length,
      samples: this.learningHistory.length,
    };
  }
}

/**
 * Create pre-trained transformer model
 */
export function createTransformerModel(sensorCount = 16) {
  return new CausalTransformer({
    inputSize: sensorCount,
    dModel: 64,
    numHeads: 4,
    numLayers: 2,
    sequenceLength: 20,
  });
}
