import { useState } from 'react';
import useStore from '../store';
import './SensorConfig.css';

function SensorConfig() {
  const {
    sensors,
    sensorType,
    samplingRate,
    maxSensors,
    setSensorType,
    setSamplingRate,
    removeSensor,
    algorithms,
    toggleAlgorithm,
  } = useStore();

  const [selectedSensor, setSelectedSensor] = useState(null);

  return (
    <div className="sensor-config">
      <div className="section">
        <h2>Sensor Configuration</h2>

        <div className="config-group">
          <label>Sensor Type</label>
          <div className="button-group">
            <button
              className={sensorType === 'capacitive' ? 'active' : ''}
              onClick={() => setSensorType('capacitive')}
            >
              Capacitive
            </button>
            <button
              className={sensorType === 'ir' ? 'active' : ''}
              onClick={() => setSensorType('ir')}
            >
              IR (Infrared)
            </button>
          </div>
          <div className="info-text">
            {sensorType === 'capacitive'
              ? '📐 Inverse-square falloff, 5cm range'
              : '📡 Exponential decay, 8cm range'}
          </div>
        </div>

        <div className="config-group">
          <label>Sampling Rate: {samplingRate} Hz</label>
          <input
            type="range"
            min="10"
            max="1000"
            step="10"
            value={samplingRate}
            onChange={(e) => setSamplingRate(Number(e.target.value))}
          />
          <div className="range-labels">
            <span>10Hz</span>
            <span>1kHz</span>
          </div>
        </div>

        <div className="config-group">
          <label>Sensors Placed: {sensors.length} / {maxSensors}</label>
          <div className="progress-bar">
            <div
              className="progress-fill"
              style={{ width: `${(sensors.length / maxSensors) * 100}%` }}
            />
          </div>
          <div className="info-text">
            Click on the gripper finger to place sensors
          </div>
        </div>
      </div>

      <div className="section">
        <h3>Placed Sensors</h3>
        <div className="sensor-list">
          {sensors.length === 0 ? (
            <div className="empty-state">
              No sensors placed yet. Click on the gripper to add sensors.
            </div>
          ) : (
            sensors.map((sensor) => (
              <div
                key={sensor.id}
                className={`sensor-item ${selectedSensor === sensor.id ? 'selected' : ''}`}
                onClick={() => setSelectedSensor(sensor.id)}
              >
                <div className="sensor-info">
                  <div className="sensor-icon">
                    {sensor.type === 'capacitive' ? '⚡' : '📡'}
                  </div>
                  <div className="sensor-details">
                    <div className="sensor-name">
                      {sensor.type === 'capacitive' ? 'Capacitive' : 'IR'} #{sensor.id % 1000}
                    </div>
                    <div className="sensor-pos">
                      {sensor.position.x.toFixed(3)}, {sensor.position.y.toFixed(3)}, {sensor.position.z.toFixed(3)}
                    </div>
                  </div>
                </div>
                <button
                  className="remove-btn"
                  onClick={(e) => {
                    e.stopPropagation();
                    removeSensor(sensor.id);
                    if (selectedSensor === sensor.id) setSelectedSensor(null);
                  }}
                >
                  ✕
                </button>
              </div>
            ))
          )}
        </div>
      </div>

      <div className="section">
        <h3>Algorithm Selection</h3>
        <div className="algorithm-list">
          {Object.entries(algorithms).map(([key, algo]) => (
            <div key={key} className="algorithm-item">
              <label className="checkbox-label">
                <input
                  type="checkbox"
                  checked={algo.enabled}
                  onChange={() => toggleAlgorithm(key)}
                />
                <span
                  className="algo-indicator"
                  style={{ background: algo.color }}
                />
                <span className="algo-name">{algo.name}</span>
              </label>
            </div>
          ))}
        </div>
        <div className="info-text">
          Enable algorithms to compete in the race
        </div>
      </div>

      <div className="section">
        <h3>Sensor Physics</h3>
        <div className="physics-info">
          <div className="physics-item">
            <div className="physics-label">Capacitive Model:</div>
            <div className="physics-formula">I = k / (d² + ε)</div>
            <div className="physics-desc">Inverse-square law with noise</div>
          </div>
          <div className="physics-item">
            <div className="physics-label">IR Model:</div>
            <div className="physics-formula">I = s × e⁻ᵅᵈ</div>
            <div className="physics-desc">Exponential decay</div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SensorConfig;
