/**
 * Physics-Informed Neural Network for Contact Prediction
 * Incorporates Hertz contact theory as soft constraints
 */

/**
 * Hertz Contact Physics Model
 * Provides physical constraints for the neural network
 */
class HertzContactModel {
  constructor(materialProperties = {}) {
    this.stiffness = materialProperties.stiffness || 1000; // N/m
    this.dampingRatio = materialProperties.dampingRatio || 0.2;
    this.effectiveRadius = materialProperties.effectiveRadius || 0.005; // 5mm
    this.effectiveModulus = materialProperties.effectiveModulus || 1e9; // Pa
  }

  /**
   * Hertz contact force: F = (4/3) * E* * sqrt(R) * δ^(3/2)
   * Simplified for small deformations: F ≈ k * δ
   */
  contactForce(penetrationDepth) {
    if (penetrationDepth <= 0) return 0;

    // Simplified linear model for small deformations
    const force = this.stiffness * penetrationDepth;
    return Math.max(0, force);
  }

  /**
   * Estimate penetration from approach velocity
   */
  estimatePenetration(velocity, mass = 0.5) {
    // Energy conservation: 0.5 * m * v^2 = 0.5 * k * δ^2
    const kineticEnergy = 0.5 * mass * velocity * velocity;
    const penetration = Math.sqrt((2 * kineticEnergy) / this.stiffness);
    return penetration;
  }

  /**
   * Time to contact from current state
   */
  timeToContact(distance, velocity) {
    if (velocity >= 0) return Infinity;
    return distance / Math.abs(velocity);
  }

  /**
   * Physics loss: penalizes predictions that violate physical laws
   */
  physicsLoss(prediction, kinematics) {
    const { contactTime, contactForce } = prediction;
    const { distance, velocity, mass } = kinematics;

    // Loss 1: Contact time should match kinematic prediction
    const physicsTime = this.timeToContact(distance, velocity);
    const timeLoss = Math.pow(contactTime - physicsTime, 2);

    // Loss 2: Contact force should match energy-based prediction
    const estimatedPenetration = this.estimatePenetration(Math.abs(velocity), mass);
    const physicsForce = this.contactForce(estimatedPenetration);
    const forceLoss = Math.pow(contactForce - physicsForce, 2);

    // Loss 3: Force should be non-negative
    const forceBoundLoss = contactForce < 0 ? Math.pow(contactForce, 2) * 10 : 0;

    // Loss 4: Time should be non-negative
    const timeBoundLoss = contactTime < 0 ? Math.pow(contactTime, 2) * 10 : 0;

    return {
      total: timeLoss + forceLoss + forceBoundLoss + timeBoundLoss,
      timeLoss,
      forceLoss,
      boundLoss: forceBoundLoss + timeBoundLoss,
    };
  }
}

/**
 * Physics-Informed Neural Network
 */
export class PhysicsInformedNN {
  constructor(config = {}) {
    const {
      inputSize = 16,
      hiddenLayers = [64, 32, 16],
      outputSize = 2,
      sequenceLength = 20,
      materialProperties = {},
    } = config;

    this.inputSize = inputSize;
    this.hiddenLayers = hiddenLayers;
    this.outputSize = outputSize;
    this.sequenceLength = sequenceLength;

    // Physics model
    this.physicsModel = new HertzContactModel(materialProperties);

    // Neural network layers
    this.weights = [];
    this.biases = [];

    // Input layer
    let prevSize = inputSize * sequenceLength; // Flatten temporal sequence
    for (const hiddenSize of hiddenLayers) {
      this.weights.push(this.initWeights(hiddenSize, prevSize));
      this.biases.push(new Array(hiddenSize).fill(0));
      prevSize = hiddenSize;
    }

    // Output layer
    this.weights.push(this.initWeights(outputSize, prevSize));
    this.biases.push(new Array(outputSize).fill(0));

    // Physics constraint weight (balance data fitting vs physics)
    this.physicsWeight = 0.3;

    // Learning history
    this.learningHistory = [];
  }

  initWeights(rows, cols) {
    const weights = [];
    for (let i = 0; i < rows; i++) {
      weights[i] = [];
      for (let j = 0; j < cols; j++) {
        // He initialization for ReLU networks
        weights[i][j] = (Math.random() - 0.5) * Math.sqrt(4 / cols);
      }
    }
    return weights;
  }

  relu(x) {
    return Math.max(0, x);
  }

  leakyRelu(x, alpha = 0.01) {
    return x > 0 ? x : alpha * x;
  }

  matmul(matrix, vector) {
    return matrix.map(row =>
      row.reduce((sum, weight, i) => sum + weight * vector[i], 0)
    );
  }

  /**
   * Forward pass through network
   */
  forward(input) {
    let activation = input;

    // Hidden layers with ReLU
    for (let i = 0; i < this.weights.length - 1; i++) {
      const z = this.matmul(this.weights[i], activation).map((val, j) =>
        val + this.biases[i][j]
      );
      activation = z.map(val => this.leakyRelu(val));
    }

    // Output layer (linear)
    const output = this.matmul(this.weights[this.weights.length - 1], activation)
      .map((val, i) => val + this.biases[this.biases.length - 1][i]);

    return output;
  }

  /**
   * Predict with physics constraints
   */
  predict(sensorSequence, kinematics = {}) {
    const {
      distance = 0.05,
      velocity = -0.05,
      mass = 0.5,
    } = kinematics;

    // Normalize sequence length
    let sequence = [...sensorSequence];
    while (sequence.length < this.sequenceLength) {
      sequence.unshift(new Array(this.inputSize).fill(0));
    }
    sequence = sequence.slice(-this.sequenceLength);

    // Flatten sequence for network input
    const flatInput = sequence.flat();

    // Neural network prediction
    const nnOutput = this.forward(flatInput);

    // Raw predictions
    let nnContactTime = Math.max(0, nnOutput[0] * 0.1);
    let nnContactForce = Math.max(0, nnOutput[1] * 10);

    // Physics-based prediction
    const physicsTime = this.physicsModel.timeToContact(distance, velocity);
    const physicsForce = this.physicsModel.contactForce(
      this.physicsModel.estimatePenetration(Math.abs(velocity), mass)
    );

    // Blend NN and physics predictions
    const w_nn = 1 - this.physicsWeight;
    const w_physics = this.physicsWeight;

    const contactTime = w_nn * nnContactTime + w_physics * physicsTime;
    const contactForce = w_nn * nnContactForce + w_physics * physicsForce;

    // Calculate physics loss for confidence estimation
    const physicsLoss = this.physicsModel.physicsLoss(
      { contactTime: nnContactTime, contactForce: nnContactForce },
      { distance, velocity, mass }
    );

    // Confidence: lower physics loss = higher confidence
    const confidence = Math.max(0, Math.min(1, 1 - physicsLoss.total / 10));

    // Apply learned corrections
    const { adjustedTime, adjustedForce } = this.applyLearning(contactTime, contactForce);

    return {
      contactTime: adjustedTime,
      contactForce: adjustedForce,
      confidence,
      rawOutput: { nnContactTime, nnContactForce },
      physicsOutput: { physicsTime, physicsForce },
      physicsLoss: physicsLoss.total,
      blendRatio: { nn: w_nn, physics: w_physics },
    };
  }

  applyLearning(contactTime, contactForce) {
    if (this.learningHistory.length < 3) {
      return { adjustedTime: contactTime, adjustedForce: contactForce };
    }

    // Adaptive physics weight based on historical performance
    const recent = this.learningHistory.slice(-10);
    const avgLoss = recent.reduce((sum, h) => sum + h.loss, 0) / recent.length;

    // If physics constraints help, increase weight; otherwise decrease
    if (avgLoss < 0.5) {
      this.physicsWeight = Math.min(0.5, this.physicsWeight + 0.02);
    } else {
      this.physicsWeight = Math.max(0.1, this.physicsWeight - 0.01);
    }

    // Error correction
    const avgTimeError = recent.reduce((sum, h) => sum + h.timeError, 0) / recent.length;
    const avgForceError = recent.reduce((sum, h) => sum + h.forceError, 0) / recent.length;

    const learningRate = 0.2;
    return {
      adjustedTime: Math.max(0, contactTime - learningRate * avgTimeError),
      adjustedForce: Math.max(0, contactForce - learningRate * avgForceError),
    };
  }

  update(prediction, groundTruth, kinematics) {
    const timeError = prediction.contactTime - groundTruth.contactTime;
    const forceError = prediction.contactForce - groundTruth.contactForce;

    const physicsLoss = this.physicsModel.physicsLoss(
      { contactTime: prediction.contactTime, contactForce: prediction.contactForce },
      kinematics
    );

    this.learningHistory.push({
      timeError,
      forceError,
      loss: physicsLoss.total,
      physicsWeight: this.physicsWeight,
      timestamp: Date.now(),
    });

    if (this.learningHistory.length > 100) {
      this.learningHistory.shift();
    }
  }

  getStats() {
    if (this.learningHistory.length === 0) {
      return {
        avgTimeError: 0,
        avgForceError: 0,
        avgPhysicsLoss: 0,
        physicsWeight: this.physicsWeight,
        samples: 0,
      };
    }

    const recent = this.learningHistory.slice(-20);
    return {
      avgTimeError: recent.reduce((sum, h) => sum + Math.abs(h.timeError), 0) / recent.length,
      avgForceError: recent.reduce((sum, h) => sum + Math.abs(h.forceError), 0) / recent.length,
      avgPhysicsLoss: recent.reduce((sum, h) => sum + h.loss, 0) / recent.length,
      physicsWeight: this.physicsWeight,
      samples: this.learningHistory.length,
    };
  }

  /**
   * Update material properties for different scenarios
   */
  setMaterialProperties(materialType) {
    const materials = {
      soft: { stiffness: 100, dampingRatio: 0.3, effectiveRadius: 0.008 },
      medium: { stiffness: 1000, dampingRatio: 0.2, effectiveRadius: 0.005 },
      rigid: { stiffness: 10000, dampingRatio: 0.1, effectiveRadius: 0.003 },
    };

    const props = materials[materialType] || materials.medium;
    this.physicsModel = new HertzContactModel(props);
  }
}

/**
 * Create pre-trained physics-informed model
 */
export function createPhysicsInformedModel(sensorCount = 16, materialType = 'medium') {
  const materials = {
    soft: { stiffness: 100, dampingRatio: 0.3 },
    medium: { stiffness: 1000, dampingRatio: 0.2 },
    rigid: { stiffness: 10000, dampingRatio: 0.1 },
  };

  return new PhysicsInformedNN({
    inputSize: sensorCount,
    hiddenLayers: [64, 32, 16],
    outputSize: 2,
    sequenceLength: 20,
    materialProperties: materials[materialType],
  });
}
