/**
 * Proximity Sensor Simulation
 * Simulates realistic sensor readings during gripper approach
 */

import { generateSensorVector } from '../utils/sensorModels.js';

/**
 * Simulate proximity readings for a trajectory
 * @param {Array} sensors - Array of sensor configurations
 * @param {Object} trajectory - Trajectory waypoints
 * @param {number} currentTime - Current simulation time
 * @returns {Object} - Sensor readings and metadata
 */
export function simulateProximityReadings(sensors, trajectory, currentTime) {
  // Find current waypoint
  const waypoint = trajectory.waypoints.find(w => w.time >= currentTime) || trajectory.waypoints[trajectory.waypoints.length - 1];

  // Object position (target is at origin)
  const objectPos = { x: 0, y: 0, z: 0 };

  // Get readings from all sensors
  const readings = sensors.map(sensor => {
    // Transform sensor position by gripper position
    const sensorWorldPos = {
      x: sensor.position.x + waypoint.position.x,
      y: sensor.position.y + waypoint.position.y,
      z: sensor.position.z + waypoint.position.z,
    };

    const sensorVector = generateSensorVector([{
      ...sensor,
      position: sensorWorldPos,
    }], objectPos);

    return {
      sensorId: sensor.id,
      reading: sensorVector[0],
      position: sensorWorldPos,
      distance: waypoint.distance,
    };
  });

  // Calculate aggregate proximity metric
  const avgReading = readings.reduce((sum, r) => sum + r.reading, 0) / readings.length;
  const maxReading = Math.max(...readings.map(r => r.reading));

  return {
    time: currentTime,
    readings,
    avgReading,
    maxReading,
    distance: waypoint.distance,
    velocity: waypoint.velocity,
  };
}

/**
 * Generate temporal sequence of sensor data
 * @param {Array} sensors - Sensor array
 * @param {Object} trajectory - Trajectory object
 * @param {number} sequenceLength - Number of time steps
 * @returns {Array} - Temporal sequence of sensor readings
 */
export function generateTemporalSequence(sensors, trajectory, sequenceLength = 20) {
  const sequence = [];
  const startTime = Math.max(0, trajectory.duration - sequenceLength * 0.01); // Last 200ms

  for (let i = 0; i < sequenceLength; i++) {
    const time = startTime + i * 0.01;
    const reading = simulateProximityReadings(sensors, trajectory, time);
    sequence.push(reading);
  }

  return sequence;
}

/**
 * Simulate sensor noise and failures
 * @param {Array} readings - Clean sensor readings
 * @param {Object} noiseConfig - Noise parameters
 * @returns {Array} - Noisy sensor readings
 */
export function addSensorNoise(readings, noiseConfig = {}) {
  const {
    gaussianNoise = 0.02,
    dropoutRate = 0.01,
    biasNoise = 0.005,
  } = noiseConfig;

  return readings.map(reading => {
    // Random dropout
    if (Math.random() < dropoutRate) {
      return { ...reading, reading: 0 };
    }

    // Gaussian noise
    const noise = (Math.random() - 0.5) * 2 * gaussianNoise;

    // Bias drift
    const bias = (Math.random() - 0.5) * biasNoise;

    return {
      ...reading,
      reading: Math.max(0, Math.min(1, reading.reading + noise + bias)),
    };
  });
}

/**
 * Calculate proximity gradient for field visualization
 * @param {Array} sensors - Sensor configurations
 * @param {Object} gripperPosition - Current gripper position
 * @param {Object} gridConfig - Grid resolution
 * @returns {Array} - 3D grid of proximity values
 */
export function calculateProximityField3D(sensors, gripperPosition, gridConfig = {}) {
  const {
    resolution = 20,
    bounds = { x: [-0.04, 0.04], y: [-0.02, 0.02], z: [0, 0.08] },
  } = gridConfig;

  const field = [];
  const objectPos = { x: 0, y: 0, z: 0 };

  for (let xi = 0; xi < resolution; xi++) {
    for (let yi = 0; yi < resolution; yi++) {
      for (let zi = 0; zi < resolution; zi++) {
        const x = bounds.x[0] + (xi / resolution) * (bounds.x[1] - bounds.x[0]);
        const y = bounds.y[0] + (yi / resolution) * (bounds.y[1] - bounds.y[0]);
        const z = bounds.z[0] + (zi / resolution) * (bounds.z[1] - bounds.z[0]);

        // Calculate field contribution from all sensors
        let fieldValue = 0;
        sensors.forEach(sensor => {
          const sensorWorldPos = {
            x: sensor.position.x + gripperPosition.x,
            y: sensor.position.y + gripperPosition.y,
            z: sensor.position.z + gripperPosition.z,
          };

          const dx = x - sensorWorldPos.x;
          const dy = y - sensorWorldPos.y;
          const dz = z - sensorWorldPos.z;
          const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

          // Inverse-square contribution
          if (dist < 0.05) {
            fieldValue += 0.001 / (dist * dist + 0.0001);
          }
        });

        field.push({
          position: { x, y, z },
          value: Math.min(1, fieldValue),
        });
      }
    }
  }

  return field;
}

/**
 * Simulate multi-rate sensor fusion
 * @param {Array} sensors - Sensors with different sampling rates
 * @param {Object} trajectory - Trajectory object
 * @param {number} currentTime - Current time
 * @returns {Object} - Fused sensor data
 */
export function multiRateSensorFusion(sensors, trajectory, currentTime) {
  const fusedData = {
    highFreq: [], // 1kHz sensors
    medFreq: [], // 100Hz sensors
    lowFreq: [], // 10Hz sensors
  };

  sensors.forEach(sensor => {
    const rate = sensor.samplingRate || 100;
    const reading = simulateProximityReadings([sensor], trajectory, currentTime);

    if (rate >= 500) {
      fusedData.highFreq.push(reading.readings[0]);
    } else if (rate >= 50) {
      fusedData.medFreq.push(reading.readings[0]);
    } else {
      fusedData.lowFreq.push(reading.readings[0]);
    }
  });

  // Weighted fusion
  const allReadings = [
    ...fusedData.highFreq.map(r => ({ ...r, weight: 1.2 })),
    ...fusedData.medFreq.map(r => ({ ...r, weight: 1.0 })),
    ...fusedData.lowFreq.map(r => ({ ...r, weight: 0.8 })),
  ];

  const totalWeight = allReadings.reduce((sum, r) => sum + r.weight, 0);
  const fusedReading = allReadings.reduce((sum, r) => sum + r.reading * r.weight, 0) / totalWeight;

  return {
    fusedReading,
    byFrequency: fusedData,
    timestamp: currentTime,
  };
}
