import { create } from 'zustand';

const useStore = create((set, get) => ({
  // Sensor configuration
  sensors: [],
  sensorType: 'capacitive', // 'capacitive' or 'ir'
  samplingRate: 100, // Hz
  maxSensors: 16,

  // Gripper state
  gripperApproachSpeed: 0.05, // m/s
  gripperDistance: 0.10, // current distance to contact, meters
  isApproaching: false,
  targetObject: 'connector',

  // Algorithm states
  algorithms: {
    gru: {
      name: 'Bidirectional GRU',
      enabled: true,
      prediction: null,
      confidence: 0,
      color: '#00ff88',
      history: [],
    },
    transformer: {
      name: 'Causal Transformer',
      enabled: true,
      prediction: null,
      confidence: 0,
      color: '#ff0088',
      history: [],
    },
    physics: {
      name: 'Physics-Informed NN',
      enabled: true,
      prediction: null,
      confidence: 0,
      color: '#0088ff',
      history: [],
    },
  },

  // Simulation state
  groundTruthContactTime: null,
  groundTruthContactForce: null,
  simulationTime: 0,
  trajectoryData: [],
  proximityReadings: [],

  // Scoring
  scores: {
    gru: { correct: 0, falsePositives: 0, avgError: 0, totalRuns: 0 },
    transformer: { correct: 0, falsePositives: 0, avgError: 0, totalRuns: 0 },
    physics: { correct: 0, falsePositives: 0, avgError: 0, totalRuns: 0 },
  },

  // UI state
  viewMode: 'editor', // 'editor', 'race', 'analysis'
  selectedAlgorithm: null,
  showProximityField: true,

  // Actions
  addSensor: (position) => set((state) => {
    if (state.sensors.length >= state.maxSensors) return state;
    return {
      sensors: [...state.sensors, {
        id: Date.now(),
        position,
        type: state.sensorType,
        active: true,
      }],
    };
  }),

  removeSensor: (id) => set((state) => ({
    sensors: state.sensors.filter(s => s.id !== id),
  })),

  updateSensorPosition: (id, position) => set((state) => ({
    sensors: state.sensors.map(s =>
      s.id === id ? { ...s, position } : s
    ),
  })),

  setSensorType: (type) => set({ sensorType: type }),
  setSamplingRate: (rate) => set({ samplingRate: rate }),

  setGripperDistance: (distance) => set({ gripperDistance: distance }),
  setApproachSpeed: (speed) => set({ gripperApproachSpeed: speed }),

  startApproach: () => set({
    isApproaching: true,
    simulationTime: 0,
    trajectoryData: [],
    proximityReadings: [],
  }),

  stopApproach: () => set({ isApproaching: false }),

  updateAlgorithmPrediction: (algorithm, prediction, confidence) => set((state) => ({
    algorithms: {
      ...state.algorithms,
      [algorithm]: {
        ...state.algorithms[algorithm],
        prediction,
        confidence,
        history: [...state.algorithms[algorithm].history, { time: state.simulationTime, prediction, confidence }],
      },
    },
  })),

  toggleAlgorithm: (algorithm) => set((state) => ({
    algorithms: {
      ...state.algorithms,
      [algorithm]: {
        ...state.algorithms[algorithm],
        enabled: !state.algorithms[algorithm].enabled,
      },
    },
  })),

  setGroundTruth: (contactTime, contactForce) => set({
    groundTruthContactTime: contactTime,
    groundTruthContactForce: contactForce,
  }),

  updateSimulationTime: (time) => set({ simulationTime: time }),

  addProximityReading: (reading) => set((state) => ({
    proximityReadings: [...state.proximityReadings, { ...reading, time: state.simulationTime }],
  })),

  updateScore: (algorithm, result) => set((state) => ({
    scores: {
      ...state.scores,
      [algorithm]: {
        ...state.scores[algorithm],
        ...result,
        totalRuns: state.scores[algorithm].totalRuns + 1,
      },
    },
  })),

  setViewMode: (mode) => set({ viewMode: mode }),
  setSelectedAlgorithm: (algorithm) => set({ selectedAlgorithm: algorithm }),
  toggleProximityField: () => set((state) => ({ showProximityField: !state.showProximityField })),

  resetSimulation: () => set({
    isApproaching: false,
    simulationTime: 0,
    trajectoryData: [],
    proximityReadings: [],
    groundTruthContactTime: null,
    groundTruthContactForce: null,
    algorithms: {
      gru: { ...get().algorithms.gru, prediction: null, confidence: 0, history: [] },
      transformer: { ...get().algorithms.transformer, prediction: null, confidence: 0, history: [] },
      physics: { ...get().algorithms.physics, prediction: null, confidence: 0, history: [] },
    },
  }),
}));

export default useStore;
