import { useState, useEffect, useRef } from 'react';
import useStore from '../store';
import { createGRUModel } from '../algorithms/gruModel';
import { createTransformerModel } from '../algorithms/transformerModel';
import { createPhysicsInformedModel } from '../algorithms/physicsInformedModel';
import { generateConnectorTrajectory, interpolateTrajectory } from '../utils/trajectoryGenerator';
import { simulateProximityReadings } from '../physics/proximitySimulator';
import { detectContact, estimateContactForce } from '../physics/contactDetection';
import { evaluatePrediction } from '../utils/scoring';
import './AlgorithmRace.css';

function AlgorithmRace() {
  const {
    sensors,
    algorithms,
    isApproaching,
    simulationTime,
    proximityReadings,
    groundTruthContactTime,
    groundTruthContactForce,
    setGroundTruth,
    updateSimulationTime,
    addProximityReading,
    updateAlgorithmPrediction,
    updateScore,
    startApproach,
    stopApproach,
    resetSimulation,
  } = useStore();

  const [models, setModels] = useState(null);
  const [trajectory, setTrajectory] = useState(null);
  const [connectorType, setConnectorType] = useState('medium');
  const [results, setResults] = useState(null);
  const animationRef = useRef();

  // Initialize models
  useEffect(() => {
    if (sensors.length > 0) {
      setModels({
        gru: createGRUModel(sensors.length),
        transformer: createTransformerModel(sensors.length),
        physics: createPhysicsInformedModel(sensors.length, connectorType),
      });
    }
  }, [sensors.length, connectorType]);

  // Generate trajectory
  const handleStartRace = () => {
    if (sensors.length === 0) {
      alert('Please place at least one sensor before starting the race!');
      return;
    }

    resetSimulation();
    const newTrajectory = generateConnectorTrajectory(connectorType);
    setTrajectory(newTrajectory);
    setGroundTruth(newTrajectory.contactTime, newTrajectory.expectedContactForce);
    setResults(null);
    startApproach();
  };

  // Simulation loop
  useEffect(() => {
    if (!isApproaching || !trajectory || !models) return;

    const dt = 0.01; // 10ms time step
    let currentTime = simulationTime;

    const simulate = () => {
      currentTime += dt;
      updateSimulationTime(currentTime);

      // Check if simulation complete
      if (currentTime >= trajectory.duration) {
        stopApproach();
        evaluateResults();
        return;
      }

      // Get current state
      const state = interpolateTrajectory(trajectory, currentTime);

      // Simulate sensor readings
      const reading = simulateProximityReadings(sensors, trajectory, currentTime);
      addProximityReading(reading);

      // Build sensor sequence for algorithms
      const recentReadings = proximityReadings.slice(-20);
      const sensorSequence = recentReadings.map(r =>
        r.readings.map(sr => sr.reading)
      );

      // Pad sequence if needed
      while (sensorSequence.length < 20) {
        sensorSequence.unshift(new Array(sensors.length).fill(0));
      }

      // Run each enabled algorithm
      if (algorithms.gru.enabled) {
        const prediction = models.gru.predict(sensorSequence);
        updateAlgorithmPrediction('gru', prediction.contactTime, prediction.confidence);
      }

      if (algorithms.transformer.enabled) {
        const prediction = models.transformer.predict(sensorSequence);
        updateAlgorithmPrediction('transformer', prediction.contactTime, prediction.confidence);
      }

      if (algorithms.physics.enabled) {
        const kinematics = {
          distance: state.distance,
          velocity: Math.sqrt(
            state.velocity.vx ** 2 + state.velocity.vy ** 2 + state.velocity.vz ** 2
          ),
          mass: 0.5,
        };
        const prediction = models.physics.predict(sensorSequence, kinematics);
        updateAlgorithmPrediction('physics', prediction.contactTime, prediction.confidence);
      }

      animationRef.current = requestAnimationFrame(simulate);
    };

    animationRef.current = requestAnimationFrame(simulate);

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [isApproaching, trajectory, models, simulationTime]);

  const evaluateResults = () => {
    const evaluations = {};

    Object.entries(algorithms).forEach(([key, algo]) => {
      if (!algo.enabled || !algo.prediction) return;

      const evaluation = evaluatePrediction(
        algo.prediction,
        groundTruthContactTime,
        0, // Force prediction not yet implemented in display
        groundTruthContactForce,
        algo.confidence
      );

      evaluations[key] = {
        ...evaluation,
        algorithmName: algo.name,
        color: algo.color,
      };

      updateScore(key, {
        correct: evaluation.isAccurate ? 1 : 0,
        falsePositives: evaluation.isFalsePositive ? 1 : 0,
        avgError: evaluation.timeError,
      });
    });

    setResults(evaluations);
  };

  const getProgressPercent = () => {
    if (!trajectory) return 0;
    return Math.min(100, (simulationTime / trajectory.duration) * 100);
  };

  return (
    <div className="algorithm-race">
      <div className="race-header">
        <h2>Algorithm Racing Arena</h2>
        <div className="race-controls">
          <div className="connector-select">
            <label>Connector Type:</label>
            <select
              value={connectorType}
              onChange={(e) => setConnectorType(e.target.value)}
              disabled={isApproaching}
            >
              <option value="soft">Soft (Rubber Gasket)</option>
              <option value="medium">Medium (Plastic)</option>
              <option value="rigid">Rigid (PCB Header)</option>
            </select>
          </div>
          <button
            className="start-btn"
            onClick={handleStartRace}
            disabled={isApproaching || sensors.length === 0}
          >
            {isApproaching ? '⏸ Running...' : '🏁 Start Race'}
          </button>
          {isApproaching && (
            <button className="stop-btn" onClick={stopApproach}>
              ⏹ Stop
            </button>
          )}
        </div>
      </div>

      {sensors.length === 0 && (
        <div className="no-sensors-warning">
          ⚠️ No sensors configured. Go to Editor mode to place sensors on the gripper.
        </div>
      )}

      <div className="race-content">
        <div className="algorithm-tracks">
          {Object.entries(algorithms).map(([key, algo]) => (
            <div
              key={key}
              className={`algorithm-track ${!algo.enabled ? 'disabled' : ''}`}
            >
              <div className="track-header">
                <div className="track-info">
                  <div
                    className="track-color"
                    style={{ background: algo.color }}
                  />
                  <div className="track-name">{algo.name}</div>
                </div>
                {algo.enabled && (
                  <div className="track-stats">
                    {algo.prediction !== null && (
                      <>
                        <div className="stat">
                          <span className="stat-label">Prediction:</span>
                          <span className="stat-value">
                            {(algo.prediction * 1000).toFixed(1)}ms
                          </span>
                        </div>
                        <div className="stat">
                          <span className="stat-label">Confidence:</span>
                          <span className="stat-value">
                            {(algo.confidence * 100).toFixed(0)}%
                          </span>
                        </div>
                      </>
                    )}
                  </div>
                )}
              </div>

              {algo.enabled && (
                <div className="track-visualization">
                  <div className="track-line">
                    {algo.prediction !== null && trajectory && (
                      <div
                        className="prediction-marker"
                        style={{
                          left: `${(algo.prediction / trajectory.duration) * 100}%`,
                          background: algo.color,
                        }}
                      />
                    )}
                    {groundTruthContactTime && trajectory && (
                      <div
                        className="ground-truth-marker"
                        style={{
                          left: `${(groundTruthContactTime / trajectory.duration) * 100}%`,
                        }}
                      />
                    )}
                  </div>
                  <div
                    className="confidence-bar"
                    style={{
                      width: `${algo.confidence * 100}%`,
                      background: algo.color,
                    }}
                  />
                </div>
              )}

              {results && results[key] && (
                <div className={`result ${results[key].isAccurate ? 'success' : 'error'}`}>
                  {results[key].isFalsePositive && (
                    <span className="false-positive">⚠️ FALSE POSITIVE</span>
                  )}
                  <span>Error: {(results[key].timeError * 1000).toFixed(2)}ms</span>
                  <span>Score: {results[key].score.toFixed(0)}</span>
                </div>
              )}
            </div>
          ))}
        </div>

        <div className="progress-section">
          <div className="progress-header">
            <span>Simulation Progress</span>
            {trajectory && (
              <span>
                {(simulationTime * 1000).toFixed(0)}ms / {(trajectory.duration * 1000).toFixed(0)}ms
              </span>
            )}
          </div>
          <div className="progress-track">
            <div
              className="progress-fill"
              style={{ width: `${getProgressPercent()}%` }}
            />
          </div>
        </div>

        {groundTruthContactTime && (
          <div className="ground-truth-panel">
            <h3>Ground Truth</h3>
            <div className="ground-truth-stats">
              <div className="gt-stat">
                <div className="gt-label">Contact Time</div>
                <div className="gt-value">{(groundTruthContactTime * 1000).toFixed(1)}ms</div>
              </div>
              <div className="gt-stat">
                <div className="gt-label">Contact Force</div>
                <div className="gt-value">{groundTruthContactForce.toFixed(2)}N</div>
              </div>
              <div className="gt-stat">
                <div className="gt-label">Connector Type</div>
                <div className="gt-value">{connectorType}</div>
              </div>
            </div>
          </div>
        )}

        {results && (
          <div className="results-panel">
            <h3>Race Results</h3>
            <div className="results-summary">
              {Object.entries(results)
                .sort((a, b) => b[1].score - a[1].score)
                .map(([key, result], idx) => (
                  <div key={key} className="result-item">
                    <div className="result-rank">#{idx + 1}</div>
                    <div className="result-info">
                      <div
                        className="result-color"
                        style={{ background: result.color }}
                      />
                      <div className="result-name">{result.algorithmName}</div>
                    </div>
                    <div className="result-metrics">
                      <div className="metric">
                        Score: <strong>{result.score.toFixed(0)}</strong>
                      </div>
                      <div className="metric">
                        Error: <strong>{(result.timeError * 1000).toFixed(2)}ms</strong>
                      </div>
                      <div className="metric">
                        {result.isFalsePositive ? (
                          <span className="fp-badge">FALSE POSITIVE</span>
                        ) : result.isAccurate ? (
                          <span className="accurate-badge">ACCURATE</span>
                        ) : (
                          <span className="late-badge">LATE</span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default AlgorithmRace;
