import { useMemo } from 'react';
import useStore from '../store';
import { calculateStatistics, compareAlgorithms } from '../utils/scoring';
import './Dashboard.css';

function Dashboard() {
  const { scores, algorithms } = useStore();

  const stats = useMemo(() => {
    const algorithmStats = {};

    Object.entries(scores).forEach(([key, score]) => {
      if (score.totalRuns === 0) {
        algorithmStats[key] = {
          avgScore: 0,
          avgTimeError: 0,
          avgForceError: 0,
          accuracyRate: 0,
          falsePositiveRate: 0,
          totalRuns: 0,
        };
      } else {
        const accuracyRate = (score.correct / score.totalRuns) * 100;
        const falsePositiveRate = (score.falsePositives / score.totalRuns) * 100;

        algorithmStats[key] = {
          avgScore: score.avgError ? -score.avgError * 100 : 0, // Simplified scoring
          avgTimeError: score.avgError || 0,
          avgForceError: 0,
          accuracyRate,
          falsePositiveRate,
          totalRuns: score.totalRuns,
        };
      }
    });

    return algorithmStats;
  }, [scores]);

  const comparison = useMemo(() => {
    if (Object.values(stats).every(s => s.totalRuns === 0)) {
      return null;
    }
    return compareAlgorithms(stats);
  }, [stats]);

  const totalRuns = useMemo(() => {
    return Object.values(scores).reduce((sum, s) => Math.max(sum, s.totalRuns), 0);
  }, [scores]);

  return (
    <div className="dashboard">
      <div className="dashboard-header">
        <h2>Performance Analysis</h2>
        <div className="total-runs">
          Total Races: <strong>{totalRuns}</strong>
        </div>
      </div>

      {totalRuns === 0 ? (
        <div className="no-data">
          <div className="no-data-icon">📊</div>
          <h3>No Race Data Yet</h3>
          <p>Run some races in the Race Arena to see performance analytics here!</p>
        </div>
      ) : (
        <>
          <div className="stats-grid">
            {Object.entries(algorithms).map(([key, algo]) => {
              const algoStats = stats[key];
              const algoScores = scores[key];

              return (
                <div
                  key={key}
                  className="stat-card"
                  style={{ borderColor: algo.color }}
                >
                  <div className="stat-card-header">
                    <div
                      className="stat-card-indicator"
                      style={{ background: algo.color }}
                    />
                    <h3>{algo.name}</h3>
                  </div>

                  <div className="stat-card-body">
                    <div className="stat-row">
                      <div className="stat-item">
                        <div className="stat-value large">
                          {algoStats.totalRuns}
                        </div>
                        <div className="stat-label">Total Runs</div>
                      </div>
                    </div>

                    <div className="stat-row">
                      <div className="stat-item">
                        <div className="stat-value">
                          {algoStats.accuracyRate.toFixed(1)}%
                        </div>
                        <div className="stat-label">Accuracy Rate</div>
                      </div>
                      <div className="stat-item">
                        <div className="stat-value error">
                          {algoStats.falsePositiveRate.toFixed(1)}%
                        </div>
                        <div className="stat-label">False Positive Rate</div>
                      </div>
                    </div>

                    <div className="stat-row">
                      <div className="stat-item">
                        <div className="stat-value">
                          {(algoStats.avgTimeError * 1000).toFixed(2)}ms
                        </div>
                        <div className="stat-label">Avg Time Error</div>
                      </div>
                      <div className="stat-item">
                        <div className="stat-value">
                          {algoScores.correct}
                        </div>
                        <div className="stat-label">Correct Predictions</div>
                      </div>
                    </div>

                    <div className="performance-bar">
                      <div
                        className="performance-fill"
                        style={{
                          width: `${algoStats.accuracyRate}%`,
                          background: algo.color,
                        }}
                      />
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {comparison && (
            <div className="comparison-panel">
              <h3>Algorithm Comparison</h3>

              <div className="winner-section">
                <div className="winner-badge">
                  🏆 Winner
                </div>
                <div className="winner-info">
                  <div
                    className="winner-indicator"
                    style={{
                      background: algorithms[comparison.winner.name]?.color || '#00ff88',
                    }}
                  />
                  <div className="winner-name">
                    {algorithms[comparison.winner.name]?.name || 'N/A'}
                  </div>
                  <div className="winner-stats">
                    <span>{comparison.winner.accuracy.toFixed(1)}% Accuracy</span>
                    <span className="separator">•</span>
                    <span>{comparison.winner.falsePositiveRate.toFixed(1)}% False Positives</span>
                  </div>
                </div>
              </div>

              <div className="ranking-table">
                <div className="table-header">
                  <div className="th rank">Rank</div>
                  <div className="th name">Algorithm</div>
                  <div className="th metric">Accuracy</div>
                  <div className="th metric">False Positives</div>
                  <div className="th metric">Avg Error</div>
                </div>
                {comparison.ranking.map((algo, idx) => {
                  const algoData = algorithms[algo.name];
                  const algoStats = stats[algo.name];

                  return (
                    <div key={algo.name} className="table-row">
                      <div className="td rank">
                        <div className="rank-badge">#{idx + 1}</div>
                      </div>
                      <div className="td name">
                        <div
                          className="algo-color"
                          style={{ background: algoData?.color }}
                        />
                        {algoData?.name}
                      </div>
                      <div className="td metric">
                        {algo.accuracy.toFixed(1)}%
                      </div>
                      <div className="td metric error">
                        {algo.falsePositiveRate.toFixed(1)}%
                      </div>
                      <div className="td metric">
                        {(algoStats.avgTimeError * 1000).toFixed(2)}ms
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <div className="insights-panel">
            <h3>Key Insights</h3>
            <div className="insights-grid">
              <div className="insight-card">
                <div className="insight-icon">⚡</div>
                <div className="insight-content">
                  <h4>Contact Prediction</h4>
                  <p>
                    Algorithms predict contact time {' '}
                    {Object.values(stats).reduce((sum, s) => sum + s.avgTimeError, 0) /
                      Object.values(stats).filter(s => s.totalRuns > 0).length > 0.02
                      ? 'with moderate accuracy'
                      : 'with high accuracy'}
                    . Continue training for better results.
                  </p>
                </div>
              </div>

              <div className="insight-card">
                <div className="insight-icon">⚠️</div>
                <div className="insight-content">
                  <h4>False Positives</h4>
                  <p>
                    False positives (premature contact predictions) can damage connectors.
                    Current rate:{' '}
                    {(
                      Object.values(stats).reduce((sum, s) => sum + s.falsePositiveRate, 0) /
                      Object.values(stats).filter(s => s.totalRuns > 0).length
                    ).toFixed(1)}%
                  </p>
                </div>
              </div>

              <div className="insight-card">
                <div className="insight-icon">🎯</div>
                <div className="insight-content">
                  <h4>Algorithm Performance</h4>
                  <p>
                    {comparison && comparison.ranking.length > 1
                      ? `${algorithms[comparison.ranking[0].name]?.name} leads with ${comparison.ranking[0].accuracy.toFixed(0)}% accuracy.`
                      : 'Run more races to compare algorithm performance.'}
                  </p>
                </div>
              </div>

              <div className="insight-card">
                <div className="insight-icon">🔬</div>
                <div className="insight-content">
                  <h4>Physics-Informed Approach</h4>
                  <p>
                    Physics-informed models incorporate Hertz contact theory to constrain
                    predictions, potentially reducing false positives.
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="methodology-panel">
            <h3>Scoring Methodology</h3>
            <div className="methodology-content">
              <div className="methodology-item">
                <div className="method-label">✅ Accurate Prediction</div>
                <div className="method-desc">
                  Within 20ms of ground truth + early prediction bonus
                </div>
                <div className="method-score">+100 to +200 points</div>
              </div>
              <div className="methodology-item">
                <div className="method-label">❌ False Positive</div>
                <div className="method-desc">
                  Predicted contact too early (damages connector scenario)
                </div>
                <div className="method-score">-50 to -500 points</div>
              </div>
              <div className="methodology-item">
                <div className="method-label">🐌 Late Prediction</div>
                <div className="method-desc">
                  Predicted after actual contact (less reaction time)
                </div>
                <div className="method-score">-10 to -50 points</div>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export default Dashboard;
