/**
 * Trajectory Generator for Approach Simulations
 * Generates realistic gripper approach trajectories with varied speeds and angles
 */

/**
 * Generate a single approach trajectory
 * @param {Object} config - Configuration parameters
 * @returns {Object} - Trajectory data with waypoints and metadata
 */
export function generateTrajectory(config = {}) {
  const {
    startDistance = 0.10, // meters
    endDistance = 0.0,
    approachSpeed = 0.05, // m/s
    approachAngle = 0, // radians, deviation from normal
    lateralOffset = 0, // meters, side-to-side offset
    samplingRate = 100, // Hz
  } = config;

  const duration = startDistance / approachSpeed;
  const numSamples = Math.floor(duration * samplingRate);
  const waypoints = [];

  for (let i = 0; i <= numSamples; i++) {
    const t = i / numSamples;
    const distance = startDistance * (1 - t);

    // Position with angle and offset
    const x = lateralOffset + Math.sin(approachAngle) * distance;
    const y = 0;
    const z = Math.cos(approachAngle) * distance;

    // Velocity
    const vx = -Math.sin(approachAngle) * approachSpeed;
    const vy = 0;
    const vz = -Math.cos(approachAngle) * approachSpeed;

    waypoints.push({
      time: t * duration,
      position: { x, y, z },
      velocity: { vx, vy, vz },
      distance,
    });
  }

  return {
    waypoints,
    duration,
    approachSpeed,
    approachAngle,
    lateralOffset,
    contactTime: duration,
  };
}

/**
 * Generate a dataset of varied trajectories for training
 * @param {number} numTrajectories - Number of trajectories to generate
 * @returns {Array} - Array of trajectory objects
 */
export function generateTrainingDataset(numTrajectories = 100) {
  const trajectories = [];

  for (let i = 0; i < numTrajectories; i++) {
    const config = {
      startDistance: 0.05 + Math.random() * 0.10, // 5-15cm
      approachSpeed: 0.02 + Math.random() * 0.08, // 2-10 cm/s
      approachAngle: (Math.random() - 0.5) * 0.3, // ±0.15 radians (±8.6 degrees)
      lateralOffset: (Math.random() - 0.5) * 0.02, // ±1cm lateral
      samplingRate: 100,
    };

    trajectories.push(generateTrajectory(config));
  }

  return trajectories;
}

/**
 * Generate realistic connector insertion trajectory
 * @param {string} connectorType - Type of connector (soft, medium, rigid)
 * @returns {Object} - Trajectory with contact characteristics
 */
export function generateConnectorTrajectory(connectorType = 'medium') {
  const configs = {
    soft: {
      stiffness: 100, // N/m (rubber gasket)
      dampingRatio: 0.3,
      contactForce: 2, // N
      approachSpeed: 0.04,
    },
    medium: {
      stiffness: 1000, // N/m (plastic connector)
      dampingRatio: 0.2,
      contactForce: 5, // N
      approachSpeed: 0.03,
    },
    rigid: {
      stiffness: 10000, // N/m (PCB header)
      dampingRatio: 0.1,
      contactForce: 10, // N
      approachSpeed: 0.02,
    },
  };

  const config = configs[connectorType] || configs.medium;
  const trajectory = generateTrajectory({
    startDistance: 0.08,
    approachSpeed: config.approachSpeed,
    approachAngle: (Math.random() - 0.5) * 0.1,
    lateralOffset: (Math.random() - 0.5) * 0.005,
  });

  return {
    ...trajectory,
    connectorType,
    stiffness: config.stiffness,
    dampingRatio: config.dampingRatio,
    expectedContactForce: config.contactForce,
  };
}

/**
 * Interpolate trajectory at specific time
 * @param {Object} trajectory - Trajectory object
 * @param {number} time - Time to interpolate at
 * @returns {Object} - Interpolated state
 */
export function interpolateTrajectory(trajectory, time) {
  const { waypoints } = trajectory;

  if (time <= 0) return waypoints[0];
  if (time >= trajectory.duration) return waypoints[waypoints.length - 1];

  // Find bounding waypoints
  let i = 0;
  while (i < waypoints.length - 1 && waypoints[i + 1].time <= time) {
    i++;
  }

  const w1 = waypoints[i];
  const w2 = waypoints[i + 1];
  const t = (time - w1.time) / (w2.time - w1.time);

  // Linear interpolation
  return {
    time,
    position: {
      x: w1.position.x + t * (w2.position.x - w1.position.x),
      y: w1.position.y + t * (w2.position.y - w1.position.y),
      z: w1.position.z + t * (w2.position.z - w1.position.z),
    },
    velocity: {
      vx: w1.velocity.vx + t * (w2.velocity.vx - w1.velocity.vx),
      vy: w1.velocity.vy + t * (w2.velocity.vy - w1.velocity.vy),
      vz: w1.velocity.vz + t * (w2.velocity.vz - w1.velocity.vz),
    },
    distance: w1.distance + t * (w2.distance - w1.distance),
  };
}
