/**
 * Sensor Models for Proximity Detection
 * Implements realistic capacitive and IR sensor response curves
 */

/**
 * Capacitive sensor model - follows inverse-square law
 * @param {number} distance - Distance to object in meters
 * @param {number} sensitivity - Sensor sensitivity (0-1)
 * @returns {number} - Normalized sensor reading (0-1)
 */
export function capacitiveSensorModel(distance, sensitivity = 0.8) {
  const maxRange = 0.05; // 5cm max range
  const k = sensitivity * 0.001; // Coupling coefficient

  if (distance >= maxRange) return 0;

  // Inverse-square law with noise
  const reading = k / (distance * distance + 0.0001);
  const noise = (Math.random() - 0.5) * 0.02; // 2% noise

  return Math.max(0, Math.min(1, reading + noise));
}

/**
 * IR sensor model - follows exponential decay
 * @param {number} distance - Distance to object in meters
 * @param {number} sensitivity - Sensor sensitivity (0-1)
 * @returns {number} - Normalized sensor reading (0-1)
 */
export function irSensorModel(distance, sensitivity = 0.8) {
  const maxRange = 0.08; // 8cm max range
  const decayRate = 25; // Exponential decay rate

  if (distance >= maxRange) return 0;

  // Exponential decay with noise
  const reading = sensitivity * Math.exp(-decayRate * distance);
  const noise = (Math.random() - 0.5) * 0.03; // 3% noise

  return Math.max(0, Math.min(1, reading + noise));
}

/**
 * Get sensor reading based on sensor type
 */
export function getSensorReading(sensorType, distance, sensitivity = 0.8) {
  switch (sensorType) {
    case 'capacitive':
      return capacitiveSensorModel(distance, sensitivity);
    case 'ir':
      return irSensorModel(distance, sensitivity);
    default:
      return 0;
  }
}

/**
 * Calculate distance from sensor to object
 * @param {Object} sensorPos - Sensor position {x, y, z}
 * @param {Object} objectPos - Object position {x, y, z}
 * @returns {number} - Distance in meters
 */
export function calculateDistance(sensorPos, objectPos) {
  const dx = sensorPos.x - objectPos.x;
  const dy = sensorPos.y - objectPos.y;
  const dz = sensorPos.z - objectPos.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

/**
 * Generate multi-sensor fusion vector
 * @param {Array} sensors - Array of sensor objects with position and type
 * @param {Object} objectPos - Object position
 * @returns {Array} - Array of sensor readings
 */
export function generateSensorVector(sensors, objectPos) {
  return sensors.map(sensor => {
    const distance = calculateDistance(sensor.position, objectPos);
    return getSensorReading(sensor.type, distance);
  });
}

/**
 * Calculate proximity gradient for visualization
 * @param {Array} sensors - Array of sensors
 * @param {Object} point - Point to evaluate {x, y, z}
 * @returns {number} - Combined proximity value
 */
export function calculateProximityField(sensors, point) {
  let totalField = 0;

  sensors.forEach(sensor => {
    const distance = calculateDistance(sensor.position, point);
    const reading = getSensorReading(sensor.type, distance);
    totalField += reading;
  });

  return Math.min(1, totalField);
}
